/**
 * 命运生成服务
 * 负责生成无厘头的卜卦结果
 */
import { minimaxClient } from '../infrastructure/MinimaxClient.js';

export class FortuneGenerator {
  constructor() {
    // Fallback 结果（当 AI 不可用时）
    this.fallbackResults = [
      {
        type: 'prediction',
        title: '神秘预知',
        text: '你将在3秒后打喷嚏。不信你数着。',
        params: { countdown: 3, effect: 'sneeze' }
      },
      {
        type: 'timetravel',
        title: '时光倒流',
        text: '回放一下：你刚才输入的时候，你妈其实在隔壁叫你。',
        params: { scene: 'mom_call' }
      },
      {
        type: 'prank',
        title: '整蛊警告',
        text: '检测到系统即将崩溃...开玩笑的，你的好运正在加载中。',
        params: { fake_error: true }
      },
      {
        type: 'mystic',
        title: '上上签',
        text: '摇出一支签：第88签。大吉。今日出门会捡到钱。',
        params: { gua: 88, level: 'super_lucky' }
      },
      {
        type: 'badluck',
        title: '今日不宜',
        text: '诸事不宜...不宜的是坏事。好运会自己找上门的！',
        params: { reversed: true }
      },
      {
        type: 'prediction',
        title: '喷嚏预言',
        text: '你刚才打喷嚏的时候，有人在想你。是谁？是你自己。',
        params: { countdown: 5, effect: 'sneeze' }
      },
      {
        type: 'timetravel',
        title: '穿越时空',
        text: '根据大数据分析，你上辈子是个无忧无虑的人。这辈子也是。',
        params: { era: 'past_life' }
      },
      {
        type: 'prank',
        title: '倒计时惊喜',
        text: '10...9...8...你的好运倒计时开始了！',
        params: { countdown: 10 }
      },
      {
        type: 'mystic',
        title: '铜钱卦',
        text: '三枚铜钱落地：阳、阴、阳。这是大吉之兆。',
        params: { coins: ['yang', 'yin', 'yang'] }
      },
      {
        type: 'badluck',
        title: '小坏运',
        text: '今天可能会摔一跤...但是会有人扶你起来。',
        params: { bad: true, mitigated: true }
      }
    ];
  }

  /**
   * 生成命运
   * @param {Object} context
   * @param {string} context.userInput - 用户输入
   * @param {string} context.style - 氛围风格
   * @param {string} context.timestamp - 当前时间戳
   * @param {string} context.randomSeed - 随机种子
   * @returns {Promise<Object>} { type, title, text, params }
   */
  async generate(context) {
    const { userInput, style, timestamp, randomSeed } = context;

    // 如果没有 API key，使用 fallback
    if (!minimaxClient.apiKey) {
      console.log('[FortuneGenerator] No API key, using fallback');
      return this.getRandomFallback();
    }

    try {
      const result = await this.callAI(context);
      return this.validateResult(result);
    } catch (error) {
      console.error('[FortuneGenerator] AI error:', error);
      return this.getRandomFallback();
    }
  }

  /**
   * 调用 AI
   */
  async callAI(context) {
    const { userInput, style, timestamp, randomSeed } = context;

    const systemPrompt = `你是一个无厘头的卜卦大师，专门生成出奇制胜、让人会心一笑的卜卦结果。

规则：
1. 必须出人意料，不能平庸
2. 要有无厘头的幽默感
3. 根据用户输入随机生成不同类型的结果
4. 每次都要不一样

类型说明：
- prediction（预知类）：预言一件即将发生的搞笑小事
- timetravel（穿越类）：穿越到某个搞笑场景
- prank（整蛊类）：先吓你一跳再反转
- mystic（玄学类）：用玄学语言包装一个搞笑结论
- badluck（坏签类）：先说不好的再说反转

返回格式（必须是严格JSON）：
{
  "type": "prediction|timetravel|prank|mystic|badluck",
  "title": "标题（5字内）",
  "text": "无厘头文案（20-50字，要出人意料）",
  "params": {
    // 类型特定参数，用于驱动动画
  }
}`;

    const userMessage = `当前时间: ${timestamp}
随机种子: ${randomSeed}
用户输入: ${userInput}
氛围风格: ${style}

请生成一个无厘头的卜卦结果。`;

    const response = await minimaxClient.chat(systemPrompt, userMessage);

    // 尝试解析 JSON
    const jsonMatch = response.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      return JSON.parse(jsonMatch[0]);
    }

    throw new Error('Failed to parse AI response');
  }

  /**
   * 验证结果结构
   */
  validateResult(result) {
    const validTypes = ['prediction', 'timetravel', 'prank', 'mystic', 'badluck'];

    if (!validTypes.includes(result.type)) {
      result.type = validTypes[Math.floor(Math.random() * validTypes.length)];
    }

    if (!result.title) result.title = '无厘头';
    if (!result.text) result.text = '这就是你的命运，自己体会吧。';
    if (!result.params) result.params = {};

    return result;
  }

  /**
   * 获取随机 fallback
   */
  getRandomFallback() {
    const index = Math.floor(Math.random() * this.fallbackResults.length);
    return this.fallbackResults[index];
  }
}

// 导出单例
export const fortuneGenerator = new FortuneGenerator();
